<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { api } from '@/lib/api/client'
import { useAuthStore } from '@/stores/auth'
import type { Document,Revision,Page,SourceRef } from '@/lib/api/types'
import { usePages } from './queries'
import SafeMarkdown from '@/features/evidence/components/SafeMarkdown.vue'
interface Chunk {chunk_uid:string;ordinal:number;text:string;metadata?:{asset_ids?:string[];source_refs?:SourceRef[]}}
const props=defineProps<{document:Document}>(),emit=defineEmits<{changed:[]}>(),auth=useAuthStore()
const id=computed(()=>props.document.document_id),query=usePages<Revision>('revisions',id,()=>`/documents/${encodeURIComponent(id.value)}/revisions`)
const revisions=computed(()=>query.data.value?.pages.flatMap(p=>p.items)||[]),selected=ref(''),compare=ref(''),error=ref(''),busy=ref(false),notice=ref('')
const chunks=usePages<Chunk>('chunks',computed(()=>id.value+'/'+selected.value),()=>`/documents/${encodeURIComponent(id.value)}/revisions/${encodeURIComponent(selected.value)}/chunks`,()=>!!selected.value&&auth.user?.role!=='viewer')
const other=usePages<Chunk>('comparison',computed(()=>id.value+'/'+compare.value),()=>`/documents/${encodeURIComponent(id.value)}/revisions/${encodeURIComponent(compare.value)}/chunks`,()=>!!compare.value&&auth.user?.role!=='viewer')
watch(id,()=>{selected.value='';compare.value='';notice.value='';error.value=''})
async function action(name:string,rid?:string){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{
  const base=`/documents/${encodeURIComponent(id.value)}`
  await api.post(name==='publish'?`${base}/revisions/${encodeURIComponent(rid!)}/publish`:`${base}/${name}`,{expected_active_revision_id:props.document.active_revision_id,...(name==='rollback'?{target_revision_id:rid}:{})})
  notice.value='操作已保存，请以刷新后的活动版本为准。';await query.refetch();emit('changed')
}catch(e){error.value=(e as Error).message;await query.refetch();emit('changed')}finally{busy.value=false}}
</script>
<template><section class="revision-panel"><header><h2>{{document.name}} · 修订</h2><p class="muted">{{document.document_id}}</p></header><p v-if="query.isPending.value" role="status">正在读取修订…</p><p v-if="query.error.value||error" role="alert">{{error||query.error.value?.message}}</p><p v-if="notice" role="status">{{notice}}</p><article v-for="r in revisions" :key="r.revision_id" class="revision-row"><strong>{{r.revision_id}}</strong><p>{{r.status}} · 尝试 {{r.attempt}}</p><p v-if="document.active_revision_id===r.revision_id">当前活动版本</p><p v-if="r.quality_flags?.length" class="quality-warning">解析质量：{{r.quality_flags.join('、')}}</p><div v-if="auth.user?.role!=='viewer'" class="actions"><button @click="selected=r.revision_id">预览切片</button><button v-if="['validated','published'].includes(r.status)&&document.active_revision_id!==r.revision_id" :disabled="busy" @click="action('publish',r.revision_id)">发布此修订</button><button v-if="['validated','published'].includes(r.status)&&document.active_revision_id&&document.active_revision_id!==r.revision_id" :disabled="busy" @click="action('rollback',r.revision_id)">回滚到此修订</button></div></article><button v-if="query.hasNextPage.value" @click="query.fetchNextPage()">更多修订</button><button v-if="auth.user?.role!=='viewer'&&document.active_revision_id" :disabled="busy" @click="action('withdraw')">撤回当前发布</button>
<template v-if="selected"><div class="comparison-toolbar"><p>当前预览：{{selected}}</p><label>对比修订<select v-model="compare"><option value="">不对比</option><option v-for="r in revisions.filter(r=>r.revision_id!==selected)" :key="r.revision_id" :value="r.revision_id">{{r.revision_id}}</option></select></label></div><div class="comparison-grid"><section><h3>预览切片</h3><p v-if="chunks.error.value" role="alert">{{chunks.error.value.message}}</p><p v-if="chunks.isPending.value" role="status">正在读取切片…</p><article v-for="c in chunks.data.value?.pages.flatMap(p=>p.items)" :key="c.chunk_uid" class="chunk-preview"><p class="eyebrow">切片 {{c.ordinal}}</p><SafeMarkdown :text="c.text" :assets="c.metadata?.asset_ids||[]"/><p v-for="(source,i) in c.metadata?.source_refs" :key="i" class="muted">{{source.section_path?.join(' / ')}} {{source.page?'页'+source.page:''}} {{source.sheet}} {{source.cell}}</p><img v-for="aid in c.metadata?.asset_ids?.filter(a=>/^[a-zA-Z0-9_-]+$/.test(a))" :key="aid" :src="'/api/v1/assets/'+encodeURIComponent(aid)" alt="切片登记图片" loading="lazy"></article><button v-if="chunks.hasNextPage.value" @click="chunks.fetchNextPage()">更多切片</button></section><section v-if="compare"><h3>对比版本</h3><p v-if="other.error.value" role="alert">{{other.error.value.message}}</p><article v-for="c in other.data.value?.pages.flatMap(p=>p.items)" :key="c.chunk_uid" class="chunk-preview"><p class="eyebrow">切片 {{c.ordinal}}</p><SafeMarkdown :text="c.text" :assets="c.metadata?.asset_ids||[]"/></article><button v-if="other.hasNextPage.value" @click="other.fetchNextPage()">更多对比切片</button></section></div></template>
</section></template>
